import{_ as t,o,c as d,a2 as r}from"./chunks/framework.BKIQXCqS.js";const u=JSON.parse('{"title":"Документация","description":"","frontmatter":{},"headers":[],"relativePath":"ru/doc.md","filePath":"ru/doc.md"}'),a={name:"ru/doc.md"};function c(s,e,i,l,h,n){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="документация" tabindex="-1">Документация <a class="header-anchor" href="#документация" aria-label="Permalink to &quot;Документация&quot;">​</a></h1><p>Расширение работает в <strong>Chrome 120</strong> и новее и в <strong>Firefox 136</strong> и новее.</p><h2 id="user-scripts" tabindex="-1">Разрешение пользовательских скриптов <a class="header-anchor" href="#user-scripts" aria-label="Permalink to &quot;Разрешение пользовательских скриптов {#user-scripts}&quot;">​</a></h2><p>Браузеры выполняют JavaScript расширения на страницах только с отдельным разрешением. Без него стили правил применяются, а JavaScript правил не выполняется; попап и страница настроек тогда подсказывают, как его включить.</p><ul><li><strong>Chrome 138 и новее:</strong> откройте сведения о расширении (<code>chrome://extensions</code> → User JavaScript and CSS → «Подробнее») и включите «Разрешить пользовательские скрипты». Режим разработчика не нужен.</li><li><strong>Chrome 120–137:</strong> включите «Режим разработчика» в правом верхнем углу <code>chrome://extensions</code>. Это <a href="https://developer.chrome.com/docs/extensions/reference/api/userScripts#developer_mode_for_extension_users" target="_blank" rel="noreferrer">требование Google</a> ко всем расширениям с пользовательскими скриптами.</li><li><strong>Firefox:</strong> нажмите «Разрешить User Scripts» в попапе и подтвердите в окне браузера. Ещё Firefox может оставить расширение без доступа к сайтам — тогда попап покажет «Разрешить доступ к сайтам», а страница настроек — «Разрешить» в плашке сверху.</li></ul><h2 id="правила" tabindex="-1">Правила <a class="header-anchor" href="#правила" aria-label="Permalink to &quot;Правила&quot;">​</a></h2><p>В контексте расширения <code>правило</code> — это JavaScript и/или CSS код, который выполняется на страницах, подходящих под его URL паттерны.</p><h3 id="url-patterns" tabindex="-1">URL паттерны <a class="header-anchor" href="#url-patterns" aria-label="Permalink to &quot;URL паттерны {#url-patterns}&quot;">​</a></h3><ul><li>Паттерн выглядит как <code>&lt;scheme&gt;://&lt;host&gt;/&lt;path&gt;</code>: <code>https://site.ru/*</code>;</li><li>Несколько паттернов пишутся через запятую: <code>https://one.ru/*, https://two.ru/*</code>;</li><li>Исключение помечается <code>!</code>: <code>!https://site.ru/admin/*</code>.</li></ul><p>Расширение переводит каждый паттерн в <a href="https://developer.chrome.com/docs/extensions/develop/concepts/match-patterns" target="_blank" rel="noreferrer">формат браузера</a>, а попап и счётчик на иконке показывают ровно те сайты, где браузер выполнит правило.</p><p><strong>Паттерн со схемой</strong> используется почти как написан:</p><table tabindex="0"><thead><tr><th>Вы пишете</th><th>Правило работает на</th></tr></thead><tbody><tr><td><code>https://site.ru/*</code></td><td><code>site.ru</code> и <code>www.site.ru</code>, но не на других поддоменах</td></tr><tr><td><code>https://*.site.ru/*</code></td><td><code>site.ru</code> и всех его поддоменах</td></tr><tr><td><code>https://site.ru/path</code></td><td>страницах, начинающихся с <code>/path</code>, на <code>site.ru</code> и <code>www.site.ru</code></td></tr><tr><td><code>https://site.ru</code></td><td>всём <code>site.ru</code> и <code>www.site.ru</code></td></tr><tr><td><code>http*://site.ru</code></td><td><code>site.ru</code> и <code>www.site.ru</code> по http и https</td></tr><tr><td><code>http://localhost:*/*</code></td><td>localhost на любом порту</td></tr></tbody></table><p><strong>Паттерн без схемы</strong> означает сайт с поддоменами по http и https:</p><table tabindex="0"><thead><tr><th>Вы пишете</th><th>Правило работает на</th></tr></thead><tbody><tr><td><code>site.ru</code>, <code>*site.ru*</code>, <code>*.site.ru</code></td><td><code>site.ru</code> и всех его поддоменах</td></tr><tr><td><code>www.site.ru</code></td><td><code>www.site.ru</code> и <code>site.ru</code></td></tr><tr><td><code>пример.рф</code></td><td><code>пример.рф</code> и его поддоменах</td></tr><tr><td><code>site.ru/path</code></td><td>страницах, начинающихся с <code>/path</code>, на <code>site.ru</code> и поддоменах</td></tr><tr><td><code>localhost:3000</code></td><td>localhost на порту 3000</td></tr><tr><td><code>/admin</code></td><td>страницах с <code>/admin</code> в пути на любом сайте</td></tr><tr><td><code>*</code></td><td>любом сайте</td></tr></tbody></table><p>Исключение со схемой используется ровно как написано: <code>https://site.ru/*, !https://www.site.ru/*</code> работает на <code>site.ru</code>, но не на <code>www.site.ru</code>. Исключение без схемы следует таблице выше: <code>!site.ru/admin</code> исключает <code>/admin</code> на <code>site.ru</code> и его поддоменах.</p><p><strong>Порты в Firefox.</strong> Паттерн Firefox не умеет указывать порт, поэтому порт отбрасывается: <code>localhost:3000</code> работает на localhost на любом порту, а исключение с портом исключает все порты хоста. Паттерн для любого сайта на одном порту (<code>*://*:8080/*</code>) стал бы паттерном для всех сайтов, поэтому в Firefox он отмечается красным.</p><p><strong>Красным отмечается</strong> паттерн, который браузер не примет: <code>*</code> внутри хоста (<code>https://shop*.site.ru/*</code>, <code>https://site.*/*</code>) или схема, где расширение не работает (<code>chrome-extension://</code>, <code>ws://</code>). Такой паттерн пропускается, остальные паттерны правила работают. Если браузер не примет исключение, правило не выполняется нигде, пока его не исправить, — иначе оно сработало бы на исключённых страницах.</p><h3 id="своиства-javascript" tabindex="-1">Свойства JavaScript <a class="header-anchor" href="#своиства-javascript" aria-label="Permalink to &quot;Свойства JavaScript&quot;">​</a></h3><p>Кнопки в шапке панели JavaScript:</p><ul><li><code>Изолированная среда</code>: скрипт видит DOM страницы, но не её переменные и функции.</li><li><code>Все фреймы</code>: код выполняется и во фреймах, адрес которых подходит под правило. Каждый фрейм проверяется по паттернам правила отдельно.</li><li><code>Запускать на старте</code>: скрипт запускается до построения DOM, иначе — после, но до загрузки ресурсов вроде изображений и фреймов. Событие <code>DOMContentLoaded</code> для такого скрипта не срабатывает.</li></ul><h3 id="своиства-стилеи" tabindex="-1">Свойства стилей <a class="header-anchor" href="#своиства-стилеи" aria-label="Permalink to &quot;Свойства стилей&quot;">​</a></h3><p>Кнопки в шапке панели стилей:</p><ul><li><code>Препроцессор Sass</code>: включён (по умолчанию) — стиль компилируется как <code>Sass</code> или <code>SCSS</code>, синтаксис определяется по наличию <code>{;}</code> в коде; выключен — стиль применяется как написан.</li><li><code>Автоматический !important на все свойства</code>: добавляет <code>!important</code> ко всем свойствам скомпилированного стиля.</li><li><code>Применять во вложенных фреймах</code>: стиль попадает и во фреймы внутри страницы. По умолчанию включено.</li><li><code>Применять в shadow DOM</code>: стиль действует и внутри веб-компонентов с открытым shadow DOM. По умолчанию выключено.</li></ul><p>Стиль меняется в открытых вкладках сразу, без перезагрузки страницы: при правке, включении правила и смене его адреса.</p><h3 id="общие-правила" tabindex="-1">Общие правила <a class="header-anchor" href="#общие-правила" aria-label="Permalink to &quot;Общие правила&quot;">​</a></h3><p>«Общие правила» позволяют выстраивать зависимости между правилами и явно задавать очерёдность их загрузки. Любое правило можно отметить как «Общее правило» в меню правила — это добавит его в список модулей остальных правил. Из подключаемого правила берётся только JS и CSS, остальные его свойства игнорируются.</p><h3 id="прошлые-версии" tabindex="-1">Прошлые версии <a class="header-anchor" href="#прошлые-версии" aria-label="Permalink to &quot;Прошлые версии&quot;">​</a></h3><p>Расширение хранит код правила до каждого из последних 10 сохранений: «Прошлые версии» в меню правила. Версия возвращается в редактор и применяется после сохранения. Версии хранятся только в этом браузере: они не попадают ни в экспорт, ни в облако.</p><h3 id="другие-особенности" tabindex="-1">Другие особенности <a class="header-anchor" href="#другие-особенности" aria-label="Permalink to &quot;Другие особенности&quot;">​</a></h3><ul><li>Маркер правила <code>включено</code> игнорируется, когда правило общее и подключается другим правилом;</li><li>Маркер <code>Сохранять в облако</code> лишь означает, что правило попадает в облачный бэкап;</li><li>«Сделать шаблоном новых правил» в меню правила: новые правила создаются с кодом и свойствами этого правила.</li></ul><h2 id="модули" tabindex="-1">Модули <a class="header-anchor" href="#модули" aria-label="Permalink to &quot;Модули&quot;">​</a></h2><p>К правилам можно подключать внешние JS и CSS модули, они запускаются до правил. Поддерживаются <code>https://...</code> ссылки, тип ресурса распознаётся по расширению.</p><p>Контент модуля скачивается и хранится в хранилище расширения. Обновляется он кнопкой «Скачать повторно» в окне редактирования модуля или по расписанию — настройка «Обновление библиотек»: вручную, раз в день или раз в неделю. Если скачать не удалось, остаётся прежняя версия модуля.</p><h2 id="хранилище" tabindex="-1">Хранилище <a class="header-anchor" href="#хранилище" aria-label="Permalink to &quot;Хранилище&quot;">​</a></h2><h3 id="локальное-хранилище" tabindex="-1">Локальное хранилище <a class="header-anchor" href="#локальное-хранилище" aria-label="Permalink to &quot;Локальное хранилище&quot;">​</a></h3><ul><li>«Скачать JSON» сохраняет ваши правила, библиотеки и настройки в файл.</li><li>«Загрузить JSON» открывает список правил и библиотек из файла. «Добавить выбранные» добавляет отмеченные к вашим: уже существующие правила заменяются, а их прежний код остаётся в прошлых версиях. «Заменить всё» заменяет ваши правила и библиотеки правилами и библиотеками из файла.</li></ul><h3 id="браузерная-синхронизация" tabindex="-1">Браузерная синхронизация <a class="header-anchor" href="#браузерная-синхронизация" aria-label="Permalink to &quot;Браузерная синхронизация&quot;">​</a></h3><p>Если в браузере включена синхронизация, резервную копию можно загрузить в облако под своим аккаунтом Google или Firefox. Такой способ не требует отдельного входа и настройки: <code>storage.sync</code> — это <a href="https://developer.chrome.com/docs/extensions/reference/api/storage#storage_areas" target="_blank" rel="noreferrer">стандартный тип синхронизации для расширений</a>. Копия загружается в облако и скачивается вручную.</p><p>Объём ограничен 100 КБ, поэтому перед загрузкой из копии убирается контент внешних модулей и все генерируемые данные, а результат сжимается. Если места всё равно не хватает, отключите «Сохранять в облако» у правил, которые в копии не нужны.</p><h2 id="mcp" tabindex="-1">Агенты (MCP) <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;Агенты (MCP) {#mcp}&quot;">​</a></h2><p>ИИ-агенты — Claude Code, Codex, Gemini CLI, Cursor, VS Code, Claude Desktop и другие — могут читать и править ваши правила через локальный MCP-сервер <a href="https://www.npmjs.com/package/user-js-css-mcp" target="_blank" rel="noreferrer">user-js-css-mcp</a>. Функция экспериментальная.</p><ol><li>Откройте раздел <strong>MCP</strong> на странице настроек и включите «Разрешить MCP-подключения».</li><li>Выберите клиент. Раздел даст готовую команду, ссылку для установки в один клик или блок конфигурации — с уже подставленным секретом подключения.</li><li>Перезапустите клиент: он сам запустит сервер, а раздел покажет, что клиент подключён.</li></ol><p>Сервер работает на вашем компьютере (<code>127.0.0.1</code>) и требует Node.js 18+ или Bun 1.2+. Расширение и сервер проверяют секрет подключения до любого запроса, поэтому другая программа на компьютере не сможет ими воспользоваться. Кнопка «Заменить» рядом с секретом отключает все клиенты, настроенные со старым секретом.</p><p>Агент может просматривать, читать, искать, создавать и менять правила и библиотеки, узнавать, какие правила работают на странице, выяснять, почему правило не работает, сохранять правила в файл и восстанавливать из него, возвращать правило к прошлой версии.</p>',44)])])}const m=t(a,[["render",c]]);export{u as __pageData,m as default};
